'use client'

import { useActionState } from 'react'

type FormState = { error?: string; success?: boolean } | null

function ContactFormFields({
  submitAction,
}: {
  submitAction: (
    prevState: FormState,
    formData: FormData
  ) => Promise<FormState>
}) {
  const [state, formAction, pending] = useActionState(submitAction, null)

  return (
    <form action={formAction}>
      <div>
        <label htmlFor="name">Name</label>
        <input id="name" name="name" type="text" required />
      </div>
      <div>
        <label htmlFor="email">Email</label>
        <input id="email" name="email" type="email" required />
      </div>
      <div>
        <label htmlFor="message">Message</label>
        <textarea id="message" name="message" required />
      </div>
      {state?.error && (
        <p role="alert" style={{ color: 'var(--color-error, red)' }}>
          {state.error}
        </p>
      )}
      {state?.success && (
        <p role="status" style={{ color: 'var(--color-success, green)' }}>
          Thank you! Your message has been sent.
        </p>
      )}
      <button type="submit" disabled={pending}>
        {pending ? 'Sending...' : 'Submit'}
      </button>
    </form>
  )
}

export default function ContactForm() {
  async function submitContactMessage(
    _prevState: FormState,
    formData: FormData
  ): Promise<FormState> {
    'use server'

    const name = formData.get('name')?.toString().trim()
    const email = formData.get('email')?.toString().trim()
    const message = formData.get('message')?.toString().trim()

    if (!name || !email || !message) {
      return { error: 'All fields are required' }
    }

    // Contact message validated and ready to save
    return { success: true }
  }

  return (
    <div>
      <h2>Contact Us</h2>
      <ContactFormFields submitAction={submitContactMessage} />
    </div>
  )
}

